<script setup lang="ts">
import { RotateCcw, FileSpreadsheet, AlertTriangle } from 'lucide-vue-next'
definePageMeta({layout:'admin',middleware:'admin'})
const me=useState<any>('auth-user'); const {data,refresh}=await useFetch('/api/admin/imports')
const notice=ref(''); const error=ref('')
async function rollback(batch:any){const msg=`Rollback impor ${batch.file_name}?\n\n${batch.rollbackable_count} lokasi akan dihapus. ${batch.modified_count} lokasi yang sudah diedit manual akan dipertahankan.`;if(!confirm(msg))return;try{const r:any=await $fetch(`/api/admin/imports/${batch.id}/rollback`,{method:'POST'});notice.value=`Rollback selesai: ${r.rolledBack} dihapus, ${r.retainedModified} data yang sudah diedit dipertahankan.`;await refresh()}catch(e:any){error.value=e?.data?.statusMessage||'Rollback gagal'}}
</script>
<template><div class="space-y-6"><UiPageHeader title="Riwayat Impor" description="Lacak sumber data Excel dan rollback batch yang salah."/>
<div v-if="notice" class="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">{{notice}}</div><div v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{error}}</div>
<UiCard class="overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">File</th><th class="px-4 py-3">Diimpor oleh</th><th class="px-4 py-3">Hasil</th><th class="px-4 py-3">Tanggal</th><th class="px-4 py-3">Status</th><th class="px-4 py-3"></th></tr></thead><tbody class="divide-y"><tr v-for="b in data?.batches||[]" :key="b.id"><td class="px-4 py-4"><div class="flex items-center gap-2 font-medium"><FileSpreadsheet class="h-4 w-4 text-emerald-600"/>{{b.file_name}}</div></td><td class="px-4 py-4"><div>{{b.imported_by_name}}</div><div class="text-xs text-slate-400">{{b.imported_by_email}}</div></td><td class="px-4 py-4 text-xs"><div>{{b.imported_rows}} diimpor · {{b.skipped_rows}} dilewati</div><div v-if="Number(b.modified_count)>0" class="mt-1 flex items-center gap-1 text-amber-700"><AlertTriangle class="h-3.5 w-3.5"/>{{b.modified_count}} diedit setelah impor</div></td><td class="px-4 py-4">{{new Date(b.created_at).toLocaleString('id-ID')}}</td><td class="px-4 py-4"><UiBadge :variant="b.rolled_back_at?'warning':'success'">{{b.rolled_back_at?'Sudah di-rollback':'Aktif'}}</UiBadge></td><td class="px-4 py-4 text-right"><UiButton v-if="!b.rolled_back_at && (me?.role==='admin' || me?.role==='manager')" variant="outline" size="sm" @click="rollback(b)"><RotateCcw class="h-4 w-4"/>Rollback</UiButton></td></tr></tbody></table></div><EmptyState v-if="!(data?.batches?.length)" title="Belum ada riwayat impor"/></UiCard></div></template>
